example_item.example_item_data:
% Dans un terminal, demarrer Ollama et telecharger un modele: % ollama serve % ollama pull llama3.2
opts = aioptions('Provider', 'ollama', ... 'Model', 'llama3.2', ... 'Endpoint', 'http://127.0.0.1:11434/api/generate', ... 'Timeout', 120, ... 'SystemPrompt', 'Retourne uniquement du code Nelson. Les fonctions Nelson utilisent la syntaxe: function y = name(x), instructions, end.', ... 'Think', false, ... 'NumPredict', 200, ... 'Temperature', 0);
answer = aiask('Ecris une fonction y = vector_mean(x). Utilise y = mean(x).', opts)

opts = aioptions('Provider', 'ollama', 'Model', 'llama3.2');
[text, response] = aiask('Explique la difference entre plot et semilogy dans Nelson.', opts);
disp(text)
disp(response.total_duration)
